#include <stdio.h> struct process_table{ int AT,BT,FT,TAT,WT; }; struct process_table process[10]; //function prototype int next_process(); int scheduling(); int main(){ int n,i,j = 0,total_time = 0,avg_tat = 0,avg_wt = 0; printf("Enter the number of processes : "); scanf("%d",&n); printf("Enter the Arrival Time and Burst Time of processes
"); for(i = 0;i < n;i ++){ printf("Details of process %d
",i+1); printf("Arrival Time : "); scanf("%d",&process[i].AT); printf("Burst Time : "); scanf("%d",&process[i].BT); } for(j = 0;j < n;j ++){ i = next_process(n); total_time += process[j].BT; process[j].FT =  total_time; } j = 0; //tat and WT for(j = 0;j < n;j ++){ process[j].TAT = process[j].FT - process[j].AT; process[j].WT = process[j].TAT - process[j].BT; } //avg tat and WT for(j = 0;j < n;j ++){ avg_wt += process[j].WT; avg_tat += process[j].TAT; } //printing result printf("Process	Burst	Finish	TAT	WT
"); for(i = 0;i < n;i ++){ printf("%d	%d	%d	%d	%d
",(i+1),process[i].BT,process[i].FT,process[i].TAT,process[i].WT); } avg_wt = avg_wt/n; avg_tat = avg_tat/n; printf("Avarage WT : %d
Avarage TAT : %d",avg_wt,avg_tat); return 0; } int next_process(int n){ int temp; for(int i = 0;i < n;i ++){ for(int j = i + 1;j < n; j ++){ if(process[i].BT > process[j].BT){ temp = j; } else if(process[i].BT == process[j].BT){ if(process[i].AT > process[j].AT){ temp = j; } else{ temp = i; } } else temp = i; } } return temp; } int scheduling(){ }
